// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ChainFactory
 * @dev Smart contract for managing blockchain deployments on PolyOne
 * Deployed on Polygon network
 */
contract ChainFactory {
    struct Chain {
        uint256 id;
        address owner;
        string name;
        string chainType; // "public", "private", "permissioned"
        string rollupType; // "zk-rollup", "optimistic-rollup", "validium"
        string gasToken;
        uint256 validators;
        uint256 createdAt;
        bool isActive;
        string rpcUrl;
        string explorerUrl;
    }

    mapping(uint256 => Chain) public chains;
    mapping(address => uint256[]) public userChains;
    uint256 public chainCount;

    event ChainCreated(
        uint256 indexed chainId,
        address indexed owner,
        string name,
        string chainType,
        string rollupType
    );

    event ChainUpdated(
        uint256 indexed chainId,
        bool isActive
    );

    event ChainDeleted(
        uint256 indexed chainId,
        address indexed owner
    );

    modifier onlyChainOwner(uint256 _chainId) {
        require(chains[_chainId].owner == msg.sender, "Not chain owner");
        _;
    }

    /**
     * @dev Create a new blockchain deployment
     */
    function createChain(
        string memory _name,
        string memory _chainType,
        string memory _rollupType,
        string memory _gasToken,
        uint256 _validators,
        string memory _rpcUrl,
        string memory _explorerUrl
    ) external returns (uint256) {
        chainCount++;
        uint256 newChainId = chainCount;

        Chain memory newChain = Chain({
            id: newChainId,
            owner: msg.sender,
            name: _name,
            chainType: _chainType,
            rollupType: _rollupType,
            gasToken: _gasToken,
            validators: _validators,
            createdAt: block.timestamp,
            isActive: true,
            rpcUrl: _rpcUrl,
            explorerUrl: _explorerUrl
        });

        chains[newChainId] = newChain;
        userChains[msg.sender].push(newChainId);

        emit ChainCreated(
            newChainId,
            msg.sender,
            _name,
            _chainType,
            _rollupType
        );

        return newChainId;
    }

    /**
     * @dev Update chain status
     */
    function updateChainStatus(uint256 _chainId, bool _isActive) 
        external 
        onlyChainOwner(_chainId) 
    {
        chains[_chainId].isActive = _isActive;
        emit ChainUpdated(_chainId, _isActive);
    }

    /**
     * @dev Delete a chain
     */
    function deleteChain(uint256 _chainId) 
        external 
        onlyChainOwner(_chainId) 
    {
        delete chains[_chainId];
        
        // Remove from user's chain list
        uint256[] storage userChainList = userChains[msg.sender];
        for (uint256 i = 0; i < userChainList.length; i++) {
            if (userChainList[i] == _chainId) {
                userChainList[i] = userChainList[userChainList.length - 1];
                userChainList.pop();
                break;
            }
        }

        emit ChainDeleted(_chainId, msg.sender);
    }

    /**
     * @dev Get all chains for a user
     */
    function getUserChains(address _user) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return userChains[_user];
    }

    /**
     * @dev Get chain details
     * Returns chain struct with all information
     */
    function getChain(uint256 _chainId) 
        external 
        view 
        returns (
            uint256 id,
            address owner,
            string memory name,
            string memory chainType,
            string memory rollupType,
            string memory gasToken,
            uint256 validators,
            uint256 createdAt,
            bool isActive,
            string memory rpcUrl,
            string memory explorerUrl
        ) 
    {
        Chain memory chain = chains[_chainId];
        require(chain.id != 0, "Chain does not exist");
        return (
            chain.id,
            chain.owner,
            chain.name,
            chain.chainType,
            chain.rollupType,
            chain.gasToken,
            chain.validators,
            chain.createdAt,
            chain.isActive,
            chain.rpcUrl,
            chain.explorerUrl
        );
    }

    /**
     * @dev Get total number of chains
     */
    function getTotalChains() external view returns (uint256) {
        return chainCount;
    }
}

contracts/ChainRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ChainRegistry
 * @dev Registry for deployed chains with metadata and verification
 */
contract ChainRegistry {
    struct ChainMetadata {
        uint256 chainId;
        address contractAddress;
        string name;
        string symbol;
        uint256 deployedBlock;
        bool verified;
        string cdkVersion;
        string zkevmVersion;
    }

    mapping(uint256 => ChainMetadata) public chainMetadata;
    mapping(address => bool) public verifiedDeployers;
    
    address public owner;
    uint256 public registeredChainCount;

    event ChainRegistered(
        uint256 indexed chainId,
        address indexed contractAddress,
        string name
    );

    event ChainVerified(
        uint256 indexed chainId,
        address verifier
    );

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
        verifiedDeployers[msg.sender] = true;
    }

    /**
     * @dev Register a new chain in the registry
     */
    function registerChain(
        uint256 _chainId,
        address _contractAddress,
        string memory _name,
        string memory _symbol,
        string memory _cdkVersion,
        string memory _zkevmVersion
    ) external {
        require(chainMetadata[_chainId].chainId == 0, "Chain already registered");

        ChainMetadata memory metadata = ChainMetadata({
            chainId: _chainId,
            contractAddress: _contractAddress,
            name: _name,
            symbol: _symbol,
            deployedBlock: block.number,
            verified: verifiedDeployers[msg.sender],
            cdkVersion: _cdkVersion,
            zkevmVersion: _zkevmVersion
        });

        chainMetadata[_chainId] = metadata;
        registeredChainCount++;

        emit ChainRegistered(_chainId, _contractAddress, _name);
    }

    /**
     * @dev Verify a chain
     */
    function verifyChain(uint256 _chainId) external onlyOwner {
        require(chainMetadata[_chainId].chainId != 0, "Chain not registered");
        
        chainMetadata[_chainId].verified = true;
        
        emit ChainVerified(_chainId, msg.sender);
    }

    /**
     * @dev Add verified deployer
     */
    function addVerifiedDeployer(address _deployer) external onlyOwner {
        verifiedDeployers[_deployer] = true;
    }

    /**
     * @dev Get chain metadata
     */
    function getChainMetadata(uint256 _chainId) 
        external 
        view 
        returns (ChainMetadata memory) 
    {
        return chainMetadata[_chainId];
    }

    /**
     * @dev Check if chain is verified
     */
    function isChainVerified(uint256 _chainId) 
        external 
        view 
        returns (bool) 
    {
        return chainMetadata[_chainId].verified;
    }
}

contracts/PolyOneBilling.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title PolyOneBilling
 * @dev Smart contract for managing subscriptions and payments on-chain
 * Features: Subscription plans, payments, invoices, usage-based billing
 */
contract PolyOneBilling is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;
    using Counters for Counters.Counter;

    // Roles
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant BILLING_ROLE = keccak256("BILLING_ROLE");

    // Subscription status
    enum SubscriptionStatus {
        Trial,
        Active,
        PastDue,
        Canceled,
        Paused,
        Expired
    }

    // Payment status
    enum PaymentStatus {
        Pending,
        Processing,
        Succeeded,
        Failed,
        Refunded
    }

    // Billing cycle
    enum BillingCycle {
        Monthly,
        Yearly
    }

    // Subscription plan struct
    struct SubscriptionPlan {
        uint256 id;
        string name;
        string slug;
        uint256 priceMonthly;
        uint256 priceYearly;
        uint256 maxChains;
        uint256 maxValidatorsPerChain;
        uint256 maxTps;
        uint256 maxStorageGb;
        uint256 maxBandwidthGb;
        uint256 maxTeamMembers;
        uint256 maxApiCallsPerMonth;
        bool bridgeEnabled;
        bool analyticsEnabled;
        bool prioritySupport;
        bool isActive;
        bool isPublic;
    }

    // Subscription struct
    struct Subscription {
        uint256 id;
        address subscriber;
        uint256 planId;
        SubscriptionStatus status;
        BillingCycle billingCycle;
        uint256 currentPeriodStart;
        uint256 currentPeriodEnd;
        uint256 trialEnd;
        uint256 canceledAt;
        uint256 createdAt;
        uint256 nextPaymentAmount;
        uint256 chainsUsed;
        uint256 storageUsedGb;
        uint256 bandwidthUsedGb;
        uint256 apiCallsUsed;
    }

    // Payment struct
    struct Payment {
        uint256 id;
        uint256 subscriptionId;
        address payer;
        uint256 amount;
        address paymentToken;
        PaymentStatus status;
        string paymentType; // "subscription", "one_time", "usage"
        uint256 periodStart;
        uint256 periodEnd;
        uint256 createdAt;
        uint256 processedAt;
        bytes32 txHash;
        string failureReason;
    }

    // Invoice struct
    struct Invoice {
        uint256 id;
        uint256 subscriptionId;
        address subscriber;
        string invoiceNumber;
        uint256 subtotal;
        uint256 tax;
        uint256 discount;
        uint256 total;
        uint256 amountDue;
        uint256 amountPaid;
        uint256 periodStart;
        uint256 periodEnd;
        uint256 dueDate;
        uint256 paidAt;
        bool isPaid;
        uint256 createdAt;
    }

    // Usage record struct
    struct UsageRecord {
        uint256 subscriptionId;
        string usageType; // "api_calls", "storage", "bandwidth"
        uint256 quantity;
        uint256 unitPrice;
        uint256 periodStart;
        uint256 periodEnd;
        bool billed;
        uint256 invoiceId;
        uint256 createdAt;
    }

    // State variables
    Counters.Counter private _planIds;
    Counters.Counter private _subscriptionIds;
    Counters.Counter private _paymentIds;
    Counters.Counter private _invoiceIds;
    Counters.Counter private _invoiceNumberCounter;

    mapping(uint256 => SubscriptionPlan) public plans;
    mapping(string => uint256) public plansBySlug;
    uint256[] public planList;

    mapping(uint256 => Subscription) public subscriptions;
    mapping(address => uint256[]) public subscriberSubscriptions;
    mapping(address => uint256) public activeSubscription;

    mapping(uint256 => Payment) public payments;
    mapping(uint256 => uint256[]) public subscriptionPayments;
    mapping(address => uint256[]) public userPayments;

    mapping(uint256 => Invoice) public invoices;
    mapping(uint256 => uint256[]) public subscriptionInvoices;

    mapping(uint256 => UsageRecord[]) public usageRecords;

    // Payment tokens
    mapping(address => bool) public acceptedPaymentTokens;
    address[] public paymentTokenList;
    address public nativePaymentToken; // For tracking native currency payments

    // Configuration
    uint256 public trialPeriod = 14 days;
    uint256 public gracePeriod = 7 days;
    address public treasury;
    uint256 public taxRate = 0; // In basis points (e.g., 1000 = 10%)

    // Discount codes
    mapping(bytes32 => uint256) public discountCodes; // code hash => discount percentage (basis points)
    mapping(bytes32 => uint256) public discountCodeUsage;
    mapping(bytes32 => uint256) public discountCodeMaxUses;

    // Events
    event PlanCreated(
        uint256 indexed planId,
        string name,
        uint256 priceMonthly,
        uint256 priceYearly,
        uint256 timestamp
    );

    event PlanUpdated(
        uint256 indexed planId,
        uint256 priceMonthly,
        uint256 priceYearly,
        bool isActive,
        uint256 timestamp
    );

    event SubscriptionCreated(
        uint256 indexed subscriptionId,
        address indexed subscriber,
        uint256 indexed planId,
        BillingCycle billingCycle,
        uint256 timestamp
    );

    event SubscriptionUpdated(
        uint256 indexed subscriptionId,
        SubscriptionStatus status,
        uint256 timestamp
    );

    event SubscriptionCanceled(
        uint256 indexed subscriptionId,
        address indexed subscriber,
        uint256 timestamp
    );

    event SubscriptionRenewed(
        uint256 indexed subscriptionId,
        uint256 newPeriodEnd,
        uint256 amount,
        uint256 timestamp
    );

    event PaymentProcessed(
        uint256 indexed paymentId,
        uint256 indexed subscriptionId,
        address indexed payer,
        uint256 amount,
        PaymentStatus status,
        uint256 timestamp
    );

    event PaymentRefunded(
        uint256 indexed paymentId,
        uint256 amount,
        uint256 timestamp
    );

    event InvoiceCreated(
        uint256 indexed invoiceId,
        uint256 indexed subscriptionId,
        string invoiceNumber,
        uint256 total,
        uint256 dueDate,
        uint256 timestamp
    );

    event InvoicePaid(
        uint256 indexed invoiceId,
        uint256 amount,
        uint256 timestamp
    );

    event UsageRecorded(
        uint256 indexed subscriptionId,
        string usageType,
        uint256 quantity,
        uint256 timestamp
    );

    event DiscountCodeCreated(
        bytes32 indexed codeHash,
        uint256 discountPercentage,
        uint256 maxUses
    );

    // Modifiers
    modifier onlySubscriber(uint256 _subscriptionId) {
        require(subscriptions[_subscriptionId].subscriber == msg.sender, "Not subscriber");
        _;
    }

    modifier subscriptionExists(uint256 _subscriptionId) {
        require(subscriptions[_subscriptionId].id != 0, "Subscription not found");
        _;
    }

    modifier planExists(uint256 _planId) {
        require(plans[_planId].id != 0, "Plan not found");
        _;
    }

    modifier acceptedToken(address _token) {
        require(acceptedPaymentTokens[_token] || _token == address(0), "Token not accepted");
        _;
    }

    constructor(address _treasury) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(BILLING_ROLE, msg.sender);

        treasury = _treasury;
    }

    // ============================================================
    // SUBSCRIPTION PLANS
    // ============================================================

    /**
     * @dev Create a new subscription plan
     */
    function createPlan(
        string memory _name,
        string memory _slug,
        uint256 _priceMonthly,
        uint256 _priceYearly,
        uint256 _maxChains,
        uint256 _maxValidatorsPerChain,
        uint256 _maxTps,
        uint256 _maxStorageGb,
        uint256 _maxBandwidthGb,
        uint256 _maxTeamMembers,
        uint256 _maxApiCallsPerMonth,
        bool _bridgeEnabled,
        bool _analyticsEnabled,
        bool _prioritySupport
    ) external onlyRole(ADMIN_ROLE) returns (uint256) {
        require(plansBySlug[_slug] == 0, "Slug already exists");

        _planIds.increment();
        uint256 planId = _planIds.current();

        SubscriptionPlan storage plan = plans[planId];
        plan.id = planId;
        plan.name = _name;
        plan.slug = _slug;
        plan.priceMonthly = _priceMonthly;
        plan.priceYearly = _priceYearly;
        plan.maxChains = _maxChains;
        plan.maxValidatorsPerChain = _maxValidatorsPerChain;
        plan.maxTps = _maxTps;
        plan.maxStorageGb = _maxStorageGb;
        plan.maxBandwidthGb = _maxBandwidthGb;
        plan.maxTeamMembers = _maxTeamMembers;
        plan.maxApiCallsPerMonth = _maxApiCallsPerMonth;
        plan.bridgeEnabled = _bridgeEnabled;
        plan.analyticsEnabled = _analyticsEnabled;
        plan.prioritySupport = _prioritySupport;
        plan.isActive = true;
        plan.isPublic = true;

        plansBySlug[_slug] = planId;
        planList.push(planId);

        emit PlanCreated(planId, _name, _priceMonthly, _priceYearly, block.timestamp);

        return planId;
    }

    /**
     * @dev Update a subscription plan
     */
    function updatePlan(
        uint256 _planId,
        uint256 _priceMonthly,
        uint256 _priceYearly,
        bool _isActive,
        bool _isPublic
    ) external onlyRole(ADMIN_ROLE) planExists(_planId) {
        SubscriptionPlan storage plan = plans[_planId];
        plan.priceMonthly = _priceMonthly;
        plan.priceYearly = _priceYearly;
        plan.isActive = _isActive;
        plan.isPublic = _isPublic;

        emit PlanUpdated(_planId, _priceMonthly, _priceYearly, _isActive, block.timestamp);
    }

    // ============================================================
    // SUBSCRIPTIONS
    // ============================================================

    /**
     * @dev Create a new subscription with payment
     */
    function subscribe(
        uint256 _planId,
        BillingCycle _billingCycle,
        address _paymentToken,
        bytes32 _discountCode
    ) external payable whenNotPaused nonReentrant planExists(_planId) acceptedToken(_paymentToken) returns (uint256) {
        SubscriptionPlan storage plan = plans[_planId];
        require(plan.isActive, "Plan not active");
        require(activeSubscription[msg.sender] == 0, "Already has active subscription");

        // Calculate price
        uint256 price = _billingCycle == BillingCycle.Monthly ? plan.priceMonthly : plan.priceYearly;

        // Apply discount if valid
        uint256 discount = 0;
        if (_discountCode != bytes32(0)) {
            discount = _applyDiscount(_discountCode, price);
        }

        uint256 finalPrice = price - discount;

        // Apply tax
        uint256 tax = (finalPrice * taxRate) / 10000;
        uint256 totalAmount = finalPrice + tax;

        // Process payment
        _processPayment(msg.sender, totalAmount, _paymentToken);

        // Create subscription
        _subscriptionIds.increment();
        uint256 subscriptionId = _subscriptionIds.current();

        uint256 periodLength = _billingCycle == BillingCycle.Monthly ? 30 days : 365 days;

        Subscription storage subscription = subscriptions[subscriptionId];
        subscription.id = subscriptionId;
        subscription.subscriber = msg.sender;
        subscription.planId = _planId;
        subscription.status = SubscriptionStatus.Active;
        subscription.billingCycle = _billingCycle;
        subscription.currentPeriodStart = block.timestamp;
        subscription.currentPeriodEnd = block.timestamp + periodLength;
        subscription.createdAt = block.timestamp;
        subscription.nextPaymentAmount = totalAmount;

        subscriberSubscriptions[msg.sender].push(subscriptionId);
        activeSubscription[msg.sender] = subscriptionId;

        // Create payment record
        _createPaymentRecord(subscriptionId, msg.sender, totalAmount, _paymentToken, "subscription");

        // Create invoice
        _createInvoice(subscriptionId, finalPrice, tax, discount, totalAmount);

        emit SubscriptionCreated(subscriptionId, msg.sender, _planId, _billingCycle, block.timestamp);

        return subscriptionId;
    }

    /**
     * @dev Start a trial subscription
     */
    function startTrial(uint256 _planId) 
        external 
        whenNotPaused 
        planExists(_planId) 
        returns (uint256) 
    {
        SubscriptionPlan storage plan = plans[_planId];
        require(plan.isActive, "Plan not active");
        require(activeSubscription[msg.sender] == 0, "Already has active subscription");

        _subscriptionIds.increment();
        uint256 subscriptionId = _subscriptionIds.current();

        Subscription storage subscription = subscriptions[subscriptionId];
        subscription.id = subscriptionId;
        subscription.subscriber = msg.sender;
        subscription.planId = _planId;
        subscription.status = SubscriptionStatus.Trial;
        subscription.billingCycle = BillingCycle.Monthly; // Default to monthly
        subscription.currentPeriodStart = block.timestamp;
        subscription.currentPeriodEnd = block.timestamp + trialPeriod;
        subscription.trialEnd = block.timestamp + trialPeriod;
        subscription.createdAt = block.timestamp;

        subscriberSubscriptions[msg.sender].push(subscriptionId);
        activeSubscription[msg.sender] = subscriptionId;

        emit SubscriptionCreated(subscriptionId, msg.sender, _planId, BillingCycle.Monthly, block.timestamp);

        return subscriptionId;
    }

    /**
     * @dev Renew subscription (can be called by anyone, usually automated)
     */
    function renewSubscription(uint256 _subscriptionId, address _paymentToken) 
        external 
        payable 
        whenNotPaused 
        nonReentrant 
        subscriptionExists(_subscriptionId)
        acceptedToken(_paymentToken)
    {
        Subscription storage subscription = subscriptions[_subscriptionId];
        require(
            subscription.status == SubscriptionStatus.Active ||
            subscription.status == SubscriptionStatus.PastDue,
            "Cannot renew"
        );
        require(block.timestamp >= subscription.currentPeriodEnd - 1 days, "Too early to renew");

        SubscriptionPlan storage plan = plans[subscription.planId];
        uint256 price = subscription.billingCycle == BillingCycle.Monthly 
            ? plan.priceMonthly 
            : plan.priceYearly;

        uint256 tax = (price * taxRate) / 10000;
        uint256 totalAmount = price + tax;

        // Process payment
        _processPayment(subscription.subscriber, totalAmount, _paymentToken);

        // Update subscription period
        uint256 periodLength = subscription.billingCycle == BillingCycle.Monthly ? 30 days : 365 days;
        subscription.currentPeriodStart = subscription.currentPeriodEnd;
        subscription.currentPeriodEnd = subscription.currentPeriodStart + periodLength;
        subscription.status = SubscriptionStatus.Active;

        // Create payment record
        _createPaymentRecord(_subscriptionId, subscription.subscriber, totalAmount, _paymentToken, "subscription");

        // Create invoice
        _createInvoice(_subscriptionId, price, tax, 0, totalAmount);

        emit SubscriptionRenewed(_subscriptionId, subscription.currentPeriodEnd, totalAmount, block.timestamp);
    }

    /**
     * @dev Cancel subscription
     */
    function cancelSubscription(uint256 _subscriptionId) 
        external 
        onlySubscriber(_subscriptionId) 
        subscriptionExists(_subscriptionId) 
    {
        Subscription storage subscription = subscriptions[_subscriptionId];
        require(
            subscription.status == SubscriptionStatus.Active ||
            subscription.status == SubscriptionStatus.Trial,
            "Cannot cancel"
        );

        subscription.status = SubscriptionStatus.Canceled;
        subscription.canceledAt = block.timestamp;
        activeSubscription[msg.sender] = 0;

        emit SubscriptionCanceled(_subscriptionId, msg.sender, block.timestamp);
    }

    /**
     * @dev Pause subscription
     */
    function pauseSubscription(uint256 _subscriptionId) 
        external 
        onlySubscriber(_subscriptionId) 
        subscriptionExists(_subscriptionId) 
    {
        Subscription storage subscription = subscriptions[_subscriptionId];
        require(subscription.status == SubscriptionStatus.Active, "Not active");

        subscription.status = SubscriptionStatus.Paused;

        emit SubscriptionUpdated(_subscriptionId, SubscriptionStatus.Paused, block.timestamp);
    }

    /**
     * @dev Resume subscription
     */
    function resumeSubscription(uint256 _subscriptionId) 
        external 
        onlySubscriber(_subscriptionId) 
        subscriptionExists(_subscriptionId) 
    {
        Subscription storage subscription = subscriptions[_subscriptionId];
        require(subscription.status == SubscriptionStatus.Paused, "Not paused");
        require(block.timestamp < subscription.currentPeriodEnd, "Period expired");

        subscription.status = SubscriptionStatus.Active;

        emit SubscriptionUpdated(_subscriptionId, SubscriptionStatus.Active, block.timestamp);
    }

    /**
     * @dev Update subscription to past due (called by billing service)
     */
    function markPastDue(uint256 _subscriptionId) 
        external 
        onlyRole(BILLING_ROLE) 
        subscriptionExists(_subscriptionId) 
    {
        Subscription storage subscription = subscriptions[_subscriptionId];
        require(
            subscription.status == SubscriptionStatus.Active,
            "Not active"
        );
        require(block.timestamp > subscription.currentPeriodEnd, "Period not ended");

        subscription.status = SubscriptionStatus.PastDue;

        emit SubscriptionUpdated(_subscriptionId, SubscriptionStatus.PastDue, block.timestamp);
    }

    /**
     * @dev Expire subscription after grace period
     */
    function expireSubscription(uint256 _subscriptionId) 
        external 
        onlyRole(BILLING_ROLE) 
        subscriptionExists(_subscriptionId) 
    {
        Subscription storage subscription = subscriptions[_subscriptionId];
        require(
            subscription.status == SubscriptionStatus.PastDue,
            "Not past due"
        );
        require(
            block.timestamp > subscription.currentPeriodEnd + gracePeriod,
            "Grace period not ended"
        );

        subscription.status = SubscriptionStatus.Expired;
        activeSubscription[subscription.subscriber] = 0;

        emit SubscriptionUpdated(_subscriptionId, SubscriptionStatus.Expired, block.timestamp);
    }

    // ============================================================
    // USAGE TRACKING
    // ============================================================

    /**
     * @dev Record usage for a subscription
     */
    function recordUsage(
        uint256 _subscriptionId,
        string memory _usageType,
        uint256 _quantity,
        uint256 _unitPrice
    ) external onlyRole(BILLING_ROLE) subscriptionExists(_subscriptionId) {
        Subscription storage subscription = subscriptions[_subscriptionId];

        UsageRecord memory record = UsageRecord({
            subscriptionId: _subscriptionId,
            usageType: _usageType,
            quantity: _quantity,
            unitPrice: _unitPrice,
            periodStart: subscription.currentPeriodStart,
            periodEnd: subscription.currentPeriodEnd,
            billed: false,
            invoiceId: 0,
            createdAt: block.timestamp
        });

        usageRecords[_subscriptionId].push(record);

        // Update subscription usage counters
        if (keccak256(bytes(_usageType)) == keccak256("api_calls")) {
            subscription.apiCallsUsed += _quantity;
        } else if (keccak256(bytes(_usageType)) == keccak256("storage")) {
            subscription.storageUsedGb += _quantity;
        } else if (keccak256(bytes(_usageType)) == keccak256("bandwidth")) {
            subscription.bandwidthUsedGb += _quantity;
        }

        emit UsageRecorded(_subscriptionId, _usageType, _quantity, block.timestamp);
    }

    /**
     * @dev Update chain count for subscription
     */
    function updateChainCount(uint256 _subscriptionId, uint256 _count) 
        external 
        onlyRole(BILLING_ROLE) 
        subscriptionExists(_subscriptionId) 
    {
        subscriptions[_subscriptionId].chainsUsed = _count;
    }

    // ============================================================
    // PAYMENT PROCESSING
    // ============================================================

    /**
     * @dev Process payment internally
     */
    function _processPayment(
        address _payer,
        uint256 _amount,
        address _paymentToken
    ) internal {
        if (_paymentToken == address(0)) {
            // Native currency payment
            require(msg.value >= _amount, "Insufficient payment");

            // Send to treasury
            payable(treasury).transfer(_amount);

            // Refund excess
            if (msg.value > _amount) {
                payable(_payer).transfer(msg.value - _amount);
            }
        } else {
            // ERC20 payment
            IERC20(_paymentToken).safeTransferFrom(_payer, treasury, _amount);
        }
    }

    /**
     * @dev Create payment record
     */
    function _createPaymentRecord(
        uint256 _subscriptionId,
        address _payer,
        uint256 _amount,
        address _paymentToken,
        string memory _paymentType
    ) internal returns (uint256) {
        _paymentIds.increment();
        uint256 paymentId = _paymentIds.current();

        Subscription storage subscription = subscriptions[_subscriptionId];

        Payment storage payment = payments[paymentId];
        payment.id = paymentId;
        payment.subscriptionId = _subscriptionId;
        payment.payer = _payer;
        payment.amount = _amount;
        payment.paymentToken = _paymentToken;
        payment.status = PaymentStatus.Succeeded;
        payment.paymentType = _paymentType;
        payment.periodStart = subscription.currentPeriodStart;
        payment.periodEnd = subscription.currentPeriodEnd;
        payment.createdAt = block.timestamp;
        payment.processedAt = block.timestamp;
        payment.txHash = bytes32(block.number);

        subscriptionPayments[_subscriptionId].push(paymentId);
        userPayments[_payer].push(paymentId);

        emit PaymentProcessed(paymentId, _subscriptionId, _payer, _amount, PaymentStatus.Succeeded, block.timestamp);

        return paymentId;
    }

    /**
     * @dev Refund a payment
     */
    function refundPayment(uint256 _paymentId, uint256 _amount) 
        external 
        onlyRole(ADMIN_ROLE) 
        nonReentrant 
    {
        Payment storage payment = payments[_paymentId];
        require(payment.status == PaymentStatus.Succeeded, "Cannot refund");
        require(_amount <= payment.amount, "Amount too high");

        payment.status = PaymentStatus.Refunded;

        if (payment.paymentToken == address(0)) {
            payable(payment.payer).transfer(_amount);
        } else {
            IERC20(payment.paymentToken).safeTransfer(payment.payer, _amount);
        }

        emit PaymentRefunded(_paymentId, _amount, block.timestamp);
    }

    // ============================================================
    // INVOICING
    // ============================================================

    /**
     * @dev Create invoice
     */
    function _createInvoice(
        uint256 _subscriptionId,
        uint256 _subtotal,
        uint256 _tax,
        uint256 _discount,
        uint256 _total
    ) internal returns (uint256) {
        _invoiceIds.increment();
        uint256 invoiceId = _invoiceIds.current();

        _invoiceNumberCounter.increment();
        string memory invoiceNumber = string(abi.encodePacked(
            "INV-",
            _uintToString(block.timestamp / (30 days)),
            "-",
            _uintToString(_invoiceNumberCounter.current())
        ));

        Subscription storage subscription = subscriptions[_subscriptionId];

        Invoice storage invoice = invoices[invoiceId];
        invoice.id = invoiceId;
        invoice.subscriptionId = _subscriptionId;
        invoice.subscriber = subscription.subscriber;
        invoice.invoiceNumber = invoiceNumber;
        invoice.subtotal = _subtotal;
        invoice.tax = _tax;
        invoice.discount = _discount;
        invoice.total = _total;
        invoice.amountDue = _total;
        invoice.amountPaid = 0; // Not paid yet - will be updated when payment is processed
        invoice.periodStart = subscription.currentPeriodStart;
        invoice.periodEnd = subscription.currentPeriodEnd;
        invoice.dueDate = subscription.currentPeriodEnd + gracePeriod; // Due after period ends plus grace period
        invoice.paidAt = 0; // Will be set when payment is confirmed
        invoice.isPaid = false; // Will be set to true when payment is confirmed
        invoice.createdAt = block.timestamp;

        subscriptionInvoices[_subscriptionId].push(invoiceId);

        emit InvoiceCreated(invoiceId, _subscriptionId, invoiceNumber, _total, invoice.dueDate, block.timestamp);

        return invoiceId;
    }

    /**
     * @dev Mark an invoice as paid (called when payment is confirmed)
     */
    function markInvoicePaid(uint256 _invoiceId, uint256 _amountPaid) 
        external 
        onlyRole(BILLING_ROLE) 
    {
        Invoice storage invoice = invoices[_invoiceId];
        require(invoice.id != 0, "Invoice not found");
        require(!invoice.isPaid, "Invoice already paid");
        require(_amountPaid > 0, "Amount must be positive");

        invoice.amountPaid += _amountPaid;

        if (invoice.amountPaid >= invoice.amountDue) {
            invoice.isPaid = true;
            invoice.paidAt = block.timestamp;
            invoice.amountDue = 0;
        } else {
            invoice.amountDue -= _amountPaid;
        }

        emit InvoicePaid(_invoiceId, _amountPaid, block.timestamp);
    }

    // ============================================================
    // DISCOUNT CODES
    // ============================================================

    /**
     * @dev Create a discount code
     */
    function createDiscountCode(
        string memory _code,
        uint256 _discountPercentage,
        uint256 _maxUses
    ) external onlyRole(ADMIN_ROLE) {
        require(_discountPercentage <= 10000, "Invalid percentage");

        bytes32 codeHash = keccak256(bytes(_code));
        require(discountCodes[codeHash] == 0, "Code already exists");

        discountCodes[codeHash] = _discountPercentage;
        discountCodeMaxUses[codeHash] = _maxUses;

        emit DiscountCodeCreated(codeHash, _discountPercentage, _maxUses);
    }

    /**
     * @dev Apply discount code
     */
    function _applyDiscount(bytes32 _codeHash, uint256 _amount) internal returns (uint256) {
        uint256 discountPercentage = discountCodes[_codeHash];
        if (discountPercentage == 0) return 0;

        uint256 maxUses = discountCodeMaxUses[_codeHash];
        if (maxUses > 0 && discountCodeUsage[_codeHash] >= maxUses) return 0;

        discountCodeUsage[_codeHash]++;
        return (_amount * discountPercentage) / 10000;
    }

    // ============================================================
    // HELPER FUNCTIONS
    // ============================================================

    function _uintToString(uint256 _value) internal pure returns (string memory) {
        if (_value == 0) return "0";

        uint256 temp = _value;
        uint256 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }

        bytes memory buffer = new bytes(digits);
        while (_value != 0) {
            digits -= 1;
            buffer[digits] = bytes1(uint8(48 + uint256(_value % 10)));
            _value /= 10;
        }

        return string(buffer);
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    function getPlan(uint256 _planId) external view returns (SubscriptionPlan memory) {
        return plans[_planId];
    }

    function getAllPlans() external view returns (uint256[] memory) {
        return planList;
    }

    function getSubscription(uint256 _subscriptionId) external view returns (Subscription memory) {
        return subscriptions[_subscriptionId];
    }

    function getUserSubscriptions(address _user) external view returns (uint256[] memory) {
        return subscriberSubscriptions[_user];
    }

    function getPayment(uint256 _paymentId) external view returns (Payment memory) {
        return payments[_paymentId];
    }

    function getSubscriptionPayments(uint256 _subscriptionId) external view returns (uint256[] memory) {
        return subscriptionPayments[_subscriptionId];
    }

    function getInvoice(uint256 _invoiceId) external view returns (Invoice memory) {
        return invoices[_invoiceId];
    }

    function getSubscriptionInvoices(uint256 _subscriptionId) external view returns (uint256[] memory) {
        return subscriptionInvoices[_subscriptionId];
    }

    function getUsageRecords(uint256 _subscriptionId) external view returns (UsageRecord[] memory) {
        return usageRecords[_subscriptionId];
    }

    function isSubscriptionActive(address _user) external view returns (bool) {
        uint256 subId = activeSubscription[_user];
        if (subId == 0) return false;

        Subscription storage sub = subscriptions[subId];
        return sub.status == SubscriptionStatus.Active || sub.status == SubscriptionStatus.Trial;
    }

    // ============================================================
    // ADMIN FUNCTIONS
    // ============================================================

    function addPaymentToken(address _token) external onlyRole(ADMIN_ROLE) {
        require(!acceptedPaymentTokens[_token], "Already accepted");
        acceptedPaymentTokens[_token] = true;
        paymentTokenList.push(_token);
    }

    function removePaymentToken(address _token) external onlyRole(ADMIN_ROLE) {
        acceptedPaymentTokens[_token] = false;
    }

    function setTreasury(address _treasury) external onlyRole(ADMIN_ROLE) {
        require(_treasury != address(0), "Invalid address");
        treasury = _treasury;
    }

    function setTaxRate(uint256 _rate) external onlyRole(ADMIN_ROLE) {
        require(_rate <= 5000, "Tax too high"); // Max 50%
        taxRate = _rate;
    }

    function setTrialPeriod(uint256 _period) external onlyRole(ADMIN_ROLE) {
        trialPeriod = _period;
    }

    function setGracePeriod(uint256 _period) external onlyRole(ADMIN_ROLE) {
        gracePeriod = _period;
    }

    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    function emergencyWithdraw(address _token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_token == address(0)) {
            payable(msg.sender).transfer(address(this).balance);
        } else {
            uint256 balance = IERC20(_token).balanceOf(address(this));
            IERC20(_token).safeTransfer(msg.sender, balance);
        }
    }

    receive() external payable {}
}

contracts/PolyOneBridge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title PolyOneBridge
 * @dev Smart contract for cross-chain token bridging
 * Features: Deposit, claim, multi-token support, fee management, security monitoring
 */
contract PolyOneBridge is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;
    using Counters for Counters.Counter;

    // Roles
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant RELAYER_ROLE = keccak256("RELAYER_ROLE");

    // Bridge transaction status
    enum BridgeStatus {
        Pending,
        Initiated,
        Processing,
        ReadyToClaim,
        Claimed,
        Completed,
        Failed,
        Refunded
    }

    // Transaction type
    enum TransactionType {
        Deposit,
        Withdraw,
        Claim,
        Transfer
    }

    // Supported token struct
    struct SupportedToken {
        address tokenAddress;
        address wrappedAddress;
        string symbol;
        string name;
        uint8 decimals;
        uint256 minAmount;
        uint256 maxAmount;
        uint256 dailyLimit;
        uint256 dailyTransferred;
        uint256 lastResetTime;
        uint256 bridgeFeePercentage; // basis points (e.g., 10 = 0.1%)
        bool isActive;
        bool isNative;
    }

    // Bridge transaction struct
    struct BridgeTransaction {
        uint256 id;
        TransactionType txType;
        BridgeStatus status;
        address sender;
        address recipient;
        address token;
        uint256 amount;
        uint256 fee;
        uint256 sourceChainId;
        uint256 destinationChainId;
        bytes32 depositHash;
        bytes32 claimHash;
        bytes32 merkleRoot;
        uint256 depositCount;
        uint256 createdAt;
        uint256 completedAt;
        string errorMessage;
    }

    // Global exit root struct for ZK proofs
    struct GlobalExitRoot {
        bytes32 mainnetExitRoot;
        bytes32 rollupExitRoot;
        uint256 timestamp;
    }

    // State variables
    Counters.Counter private _transactionIds;
    Counters.Counter private _depositCount;

    mapping(uint256 => BridgeTransaction) public transactions;
    mapping(address => uint256[]) public userTransactions;
    mapping(address => SupportedToken) public supportedTokens;
    address[] public tokenList;

    mapping(bytes32 => bool) public processedDeposits;
    mapping(bytes32 => bool) public processedClaims;
    mapping(uint256 => GlobalExitRoot) public globalExitRoots;

    mapping(uint256 => bool) public supportedDestinationChains;
    mapping(uint256 => address) public destinationBridgeContracts;

    // Fee configuration
    uint256 public baseBridgeFee = 10; // 0.1% in basis points
    uint256 public minBridgeFee = 0.001 ether;
    uint256 public maxBridgeFee = 10 ether;
    address public feeCollector;
    uint256 public collectedFees;

    // Security configuration
    uint256 public depositCooldown = 1 minutes;
    mapping(address => uint256) public lastDeposit;
    uint256 public maxPendingTransactions = 100;
    uint256 public currentPendingCount;

    // Events
    event TokenAdded(
        address indexed token,
        string symbol,
        uint256 minAmount,
        uint256 maxAmount,
        uint256 timestamp
    );

    event TokenUpdated(
        address indexed token,
        uint256 minAmount,
        uint256 maxAmount,
        bool isActive,
        uint256 timestamp
    );

    event TokenRemoved(
        address indexed token,
        uint256 timestamp
    );

    event DepositInitiated(
        uint256 indexed transactionId,
        address indexed sender,
        address indexed token,
        uint256 amount,
        uint256 destinationChainId,
        bytes32 depositHash,
        uint256 timestamp
    );

    event DepositConfirmed(
        uint256 indexed transactionId,
        bytes32 merkleRoot,
        uint256 depositCount,
        uint256 timestamp
    );

    event ClaimInitiated(
        uint256 indexed transactionId,
        address indexed recipient,
        address indexed token,
        uint256 amount,
        uint256 sourceChainId,
        uint256 timestamp
    );

    event ClaimCompleted(
        uint256 indexed transactionId,
        address indexed recipient,
        uint256 amount,
        uint256 timestamp
    );

    event TransactionFailed(
        uint256 indexed transactionId,
        string reason,
        uint256 timestamp
    );

    event TransactionRefunded(
        uint256 indexed transactionId,
        address indexed recipient,
        uint256 amount,
        uint256 timestamp
    );

    event GlobalExitRootUpdated(
        bytes32 mainnetExitRoot,
        bytes32 rollupExitRoot,
        uint256 timestamp
    );

    event FeesCollected(
        address indexed collector,
        uint256 amount,
        uint256 timestamp
    );

    event DestinationChainUpdated(
        uint256 indexed chainId,
        bool supported,
        address bridgeContract,
        uint256 timestamp
    );

    // Modifiers
    modifier validToken(address _token) {
        require(supportedTokens[_token].isActive, "Token not supported");
        _;
    }

    modifier validDestination(uint256 _chainId) {
        require(supportedDestinationChains[_chainId], "Destination chain not supported");
        _;
    }

    modifier cooldownPassed() {
        require(
            block.timestamp >= lastDeposit[msg.sender] + depositCooldown,
            "Cooldown not passed"
        );
        _;
    }

    constructor(address _feeCollector) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(OPERATOR_ROLE, msg.sender);
        _grantRole(RELAYER_ROLE, msg.sender);

        feeCollector = _feeCollector;
    }

    // ============================================================
    // TOKEN MANAGEMENT
    // ============================================================

    /**
     * @dev Add a supported token
     */
    function addSupportedToken(
        address _token,
        address _wrappedAddress,
        string memory _symbol,
        string memory _name,
        uint8 _decimals,
        uint256 _minAmount,
        uint256 _maxAmount,
        uint256 _dailyLimit,
        uint256 _bridgeFeePercentage,
        bool _isNative
    ) external onlyRole(ADMIN_ROLE) {
        require(_token != address(0), "Invalid token address");
        require(!supportedTokens[_token].isActive, "Token already added");
        require(_minAmount < _maxAmount, "Invalid amount range");
        require(_bridgeFeePercentage <= 1000, "Fee too high"); // Max 10%

        SupportedToken storage token = supportedTokens[_token];
        token.tokenAddress = _token;
        token.wrappedAddress = _wrappedAddress;
        token.symbol = _symbol;
        token.name = _name;
        token.decimals = _decimals;
        token.minAmount = _minAmount;
        token.maxAmount = _maxAmount;
        token.dailyLimit = _dailyLimit;
        token.bridgeFeePercentage = _bridgeFeePercentage;
        token.isActive = true;
        token.isNative = _isNative;
        token.lastResetTime = block.timestamp;

        tokenList.push(_token);

        emit TokenAdded(_token, _symbol, _minAmount, _maxAmount, block.timestamp);
    }

    /**
     * @dev Update a supported token
     */
    function updateSupportedToken(
        address _token,
        uint256 _minAmount,
        uint256 _maxAmount,
        uint256 _dailyLimit,
        uint256 _bridgeFeePercentage,
        bool _isActive
    ) external onlyRole(ADMIN_ROLE) {
        require(supportedTokens[_token].tokenAddress != address(0), "Token not found");

        SupportedToken storage token = supportedTokens[_token];
        token.minAmount = _minAmount;
        token.maxAmount = _maxAmount;
        token.dailyLimit = _dailyLimit;
        token.bridgeFeePercentage = _bridgeFeePercentage;
        token.isActive = _isActive;

        emit TokenUpdated(_token, _minAmount, _maxAmount, _isActive, block.timestamp);
    }

    /**
     * @dev Remove a supported token
     */
    function removeSupportedToken(address _token) external onlyRole(ADMIN_ROLE) {
        require(supportedTokens[_token].isActive, "Token not active");

        supportedTokens[_token].isActive = false;

        emit TokenRemoved(_token, block.timestamp);
    }

    // ============================================================
    // DEPOSIT (Source Chain)
    // ============================================================

    /**
     * @dev Initiate a deposit to bridge tokens
     */
    function deposit(
        address _token,
        uint256 _amount,
        uint256 _destinationChainId,
        address _recipient
    ) 
        external 
        payable 
        whenNotPaused 
        nonReentrant 
        validToken(_token) 
        validDestination(_destinationChainId)
        cooldownPassed
        returns (uint256) 
    {
        require(_amount > 0, "Amount must be positive");
        require(_recipient != address(0), "Invalid recipient");
        require(currentPendingCount < maxPendingTransactions, "Too many pending transactions");

        SupportedToken storage token = supportedTokens[_token];
        require(_amount >= token.minAmount, "Amount below minimum");
        require(_amount <= token.maxAmount, "Amount above maximum");

        // Check and update daily limit
        _checkAndUpdateDailyLimit(_token, _amount);

        // Calculate fee
        uint256 fee = calculateBridgeFee(_token, _amount);
        uint256 netAmount = _amount - fee;

        // Transfer tokens from user
        IERC20(_token).safeTransferFrom(msg.sender, address(this), _amount);

        // Create transaction
        _transactionIds.increment();
        uint256 transactionId = _transactionIds.current();

        _depositCount.increment();
        uint256 depositNum = _depositCount.current();

        bytes32 depositHash = keccak256(abi.encodePacked(
            transactionId,
            msg.sender,
            _recipient,
            _token,
            _amount,
            block.chainid,
            _destinationChainId,
            block.timestamp
        ));

        BridgeTransaction storage transaction = transactions[transactionId];
        transaction.id = transactionId;
        transaction.txType = TransactionType.Deposit;
        transaction.status = BridgeStatus.Initiated;
        transaction.sender = msg.sender;
        transaction.recipient = _recipient;
        transaction.token = _token;
        transaction.amount = netAmount;
        transaction.fee = fee;
        transaction.sourceChainId = block.chainid;
        transaction.destinationChainId = _destinationChainId;
        transaction.depositHash = depositHash;
        transaction.depositCount = depositNum;
        transaction.createdAt = block.timestamp;

        userTransactions[msg.sender].push(transactionId);
        lastDeposit[msg.sender] = block.timestamp;
        currentPendingCount++;
        collectedFees += fee;

        emit DepositInitiated(
            transactionId,
            msg.sender,
            _token,
            netAmount,
            _destinationChainId,
            depositHash,
            block.timestamp
        );

        return transactionId;
    }

    /**
     * @dev Deposit native token (ETH/MATIC)
     */
    function depositNative(
        uint256 _destinationChainId,
        address _recipient
    ) 
        external 
        payable 
        whenNotPaused 
        nonReentrant 
        validDestination(_destinationChainId)
        cooldownPassed
        returns (uint256) 
    {
        require(msg.value > 0, "Amount must be positive");
        require(_recipient != address(0), "Invalid recipient");

        // Calculate fee
        uint256 fee = (msg.value * baseBridgeFee) / 10000;
        if (fee < minBridgeFee) fee = minBridgeFee;
        if (fee > maxBridgeFee) fee = maxBridgeFee;

        uint256 netAmount = msg.value - fee;
        require(netAmount > 0, "Amount too small after fee");

        // Create transaction
        _transactionIds.increment();
        uint256 transactionId = _transactionIds.current();

        _depositCount.increment();
        uint256 depositNum = _depositCount.current();

        bytes32 depositHash = keccak256(abi.encodePacked(
            transactionId,
            msg.sender,
            _recipient,
            address(0), // Native token
            msg.value,
            block.chainid,
            _destinationChainId,
            block.timestamp
        ));

        BridgeTransaction storage transaction = transactions[transactionId];
        transaction.id = transactionId;
        transaction.txType = TransactionType.Deposit;
        transaction.status = BridgeStatus.Initiated;
        transaction.sender = msg.sender;
        transaction.recipient = _recipient;
        transaction.token = address(0);
        transaction.amount = netAmount;
        transaction.fee = fee;
        transaction.sourceChainId = block.chainid;
        transaction.destinationChainId = _destinationChainId;
        transaction.depositHash = depositHash;
        transaction.depositCount = depositNum;
        transaction.createdAt = block.timestamp;

        userTransactions[msg.sender].push(transactionId);
        lastDeposit[msg.sender] = block.timestamp;
        currentPendingCount++;
        collectedFees += fee;

        emit DepositInitiated(
            transactionId,
            msg.sender,
            address(0),
            netAmount,
            _destinationChainId,
            depositHash,
            block.timestamp
        );

        return transactionId;
    }

    /**
     * @dev Confirm deposit with merkle root (called by relayer)
     */
    function confirmDeposit(
        uint256 _transactionId,
        bytes32 _merkleRoot
    ) external onlyRole(RELAYER_ROLE) {
        BridgeTransaction storage transaction = transactions[_transactionId];
        require(transaction.status == BridgeStatus.Initiated, "Invalid status");

        transaction.merkleRoot = _merkleRoot;
        transaction.status = BridgeStatus.ReadyToClaim;

        emit DepositConfirmed(_transactionId, _merkleRoot, transaction.depositCount, block.timestamp);
    }

    // ============================================================
    // CLAIM (Destination Chain)
    // ============================================================

    /**
     * @dev Claim bridged tokens on destination chain
     */
    function claim(
        uint256 _transactionId,
        bytes32[] calldata _merkleProof,
        bytes32 _depositHash,
        address _token,
        uint256 _amount,
        address _recipient
    ) external whenNotPaused nonReentrant {
        require(!processedClaims[_depositHash], "Already claimed");
        require(_recipient != address(0), "Invalid recipient");
        require(_amount > 0, "Invalid amount");

        // Verify merkle proof
        bytes32 leaf = keccak256(abi.encodePacked(
            _transactionId,
            _depositHash,
            _token,
            _amount,
            _recipient
        ));

        BridgeTransaction storage transaction = transactions[_transactionId];
        require(
            MerkleProof.verify(_merkleProof, transaction.merkleRoot, leaf),
            "Invalid merkle proof"
        );

        processedClaims[_depositHash] = true;
        transaction.status = BridgeStatus.Claimed;
        transaction.completedAt = block.timestamp;

        // Transfer tokens to recipient
        if (_token == address(0)) {
            // Native token
            payable(_recipient).transfer(_amount);
        } else {
            IERC20(_token).safeTransfer(_recipient, _amount);
        }

        currentPendingCount--;

        emit ClaimCompleted(_transactionId, _recipient, _amount, block.timestamp);
    }

    /**
     * @dev Emergency claim without proof (admin only)
     */
    function emergencyClaim(
        uint256 _transactionId,
        address _token,
        uint256 _amount,
        address _recipient
    ) external onlyRole(ADMIN_ROLE) nonReentrant {
        BridgeTransaction storage transaction = transactions[_transactionId];
        require(transaction.status != BridgeStatus.Claimed, "Already claimed");
        require(transaction.status != BridgeStatus.Refunded, "Already refunded");

        transaction.status = BridgeStatus.Claimed;
        transaction.completedAt = block.timestamp;

        if (_token == address(0)) {
            payable(_recipient).transfer(_amount);
        } else {
            IERC20(_token).safeTransfer(_recipient, _amount);
        }

        currentPendingCount--;

        emit ClaimCompleted(_transactionId, _recipient, _amount, block.timestamp);
    }

    // ============================================================
    // REFUNDS
    // ============================================================

    /**
     * @dev Refund a failed transaction
     */
    function refund(uint256 _transactionId) 
        external 
        onlyRole(OPERATOR_ROLE) 
        nonReentrant 
    {
        BridgeTransaction storage transaction = transactions[_transactionId];
        require(
            transaction.status == BridgeStatus.Failed || 
            transaction.status == BridgeStatus.Initiated,
            "Cannot refund"
        );
        require(!processedDeposits[transaction.depositHash], "Deposit processed");

        uint256 refundAmount = transaction.amount + transaction.fee;
        transaction.status = BridgeStatus.Refunded;

        if (transaction.token == address(0)) {
            payable(transaction.sender).transfer(refundAmount);
        } else {
            IERC20(transaction.token).safeTransfer(transaction.sender, refundAmount);
        }

        collectedFees -= transaction.fee;
        currentPendingCount--;

        emit TransactionRefunded(
            _transactionId,
            transaction.sender,
            refundAmount,
            block.timestamp
        );
    }

    // ============================================================
    // GLOBAL EXIT ROOT
    // ============================================================

    /**
     * @dev Update global exit root
     */
    function updateGlobalExitRoot(
        bytes32 _mainnetExitRoot,
        bytes32 _rollupExitRoot
    ) external onlyRole(RELAYER_ROLE) {
        uint256 rootIndex = block.number;

        globalExitRoots[rootIndex] = GlobalExitRoot({
            mainnetExitRoot: _mainnetExitRoot,
            rollupExitRoot: _rollupExitRoot,
            timestamp: block.timestamp
        });

        emit GlobalExitRootUpdated(_mainnetExitRoot, _rollupExitRoot, block.timestamp);
    }

    // ============================================================
    // FEE MANAGEMENT
    // ============================================================

    /**
     * @dev Calculate bridge fee for a token
     */
    function calculateBridgeFee(address _token, uint256 _amount) public view returns (uint256) {
        SupportedToken storage token = supportedTokens[_token];
        uint256 feePercentage = token.bridgeFeePercentage > 0 ? token.bridgeFeePercentage : baseBridgeFee;

        uint256 fee = (_amount * feePercentage) / 10000;

        if (fee < minBridgeFee) fee = minBridgeFee;
        if (fee > maxBridgeFee) fee = maxBridgeFee;

        return fee;
    }

    /**
     * @dev Collect accumulated fees
     */
    function collectFees() external nonReentrant {
        require(msg.sender == feeCollector, "Not fee collector");
        require(collectedFees > 0, "No fees to collect");

        uint256 amount = collectedFees;
        collectedFees = 0;

        // Only transfer the collected fees amount, not the entire contract balance
        // This prevents accidentally transferring user deposits and bridge tokens
        payable(feeCollector).transfer(amount);

        emit FeesCollected(feeCollector, amount, block.timestamp);
    }

    /**
     * @dev Collect token fees
     */
    function collectTokenFees(address _token) external nonReentrant {
        require(msg.sender == feeCollector, "Not fee collector");

        uint256 balance = IERC20(_token).balanceOf(address(this));
        require(balance > 0, "No token balance");

        IERC20(_token).safeTransfer(feeCollector, balance);

        emit FeesCollected(feeCollector, balance, block.timestamp);
    }

    // ============================================================
    // HELPER FUNCTIONS
    // ============================================================

    /**
     * @dev Check and update daily limit
     */
    function _checkAndUpdateDailyLimit(address _token, uint256 _amount) internal {
        SupportedToken storage token = supportedTokens[_token];

        // Reset daily limit if 24 hours passed
        if (block.timestamp >= token.lastResetTime + 1 days) {
            token.dailyTransferred = 0;
            token.lastResetTime = block.timestamp;
        }

        require(
            token.dailyTransferred + _amount <= token.dailyLimit,
            "Daily limit exceeded"
        );

        token.dailyTransferred += _amount;
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    /**
     * @dev Get transaction details
     */
    function getTransaction(uint256 _transactionId) external view returns (BridgeTransaction memory) {
        return transactions[_transactionId];
    }

    /**
     * @dev Get user transactions
     */
    function getUserTransactions(address _user) external view returns (uint256[] memory) {
        return userTransactions[_user];
    }

    /**
     * @dev Get supported token details
     */
    function getSupportedToken(address _token) external view returns (SupportedToken memory) {
        return supportedTokens[_token];
    }

    /**
     * @dev Get all supported tokens
     */
    function getAllSupportedTokens() external view returns (address[] memory) {
        return tokenList;
    }

    /**
     * @dev Get global exit root
     */
    function getGlobalExitRoot(uint256 _blockNumber) external view returns (GlobalExitRoot memory) {
        return globalExitRoots[_blockNumber];
    }

    /**
     * @dev Get total transactions count
     */
    function getTotalTransactions() external view returns (uint256) {
        return _transactionIds.current();
    }

    /**
     * @dev Get current deposit count
     */
    function getDepositCount() external view returns (uint256) {
        return _depositCount.current();
    }

    // ============================================================
    // ADMIN FUNCTIONS
    // ============================================================

    /**
     * @dev Add/update destination chain
     */
    function setDestinationChain(
        uint256 _chainId,
        bool _supported,
        address _bridgeContract
    ) external onlyRole(ADMIN_ROLE) {
        supportedDestinationChains[_chainId] = _supported;
        destinationBridgeContracts[_chainId] = _bridgeContract;

        emit DestinationChainUpdated(_chainId, _supported, _bridgeContract, block.timestamp);
    }

    /**
     * @dev Update fee configuration
     */
    function setFeeConfig(
        uint256 _baseFee,
        uint256 _minFee,
        uint256 _maxFee
    ) external onlyRole(ADMIN_ROLE) {
        require(_baseFee <= 1000, "Base fee too high"); // Max 10%
        baseBridgeFee = _baseFee;
        minBridgeFee = _minFee;
        maxBridgeFee = _maxFee;
    }

    /**
     * @dev Update fee collector
     */
    function setFeeCollector(address _newCollector) external onlyRole(ADMIN_ROLE) {
        require(_newCollector != address(0), "Invalid address");
        feeCollector = _newCollector;
    }

    /**
     * @dev Update security configuration
     */
    function setSecurityConfig(
        uint256 _cooldown,
        uint256 _maxPending
    ) external onlyRole(ADMIN_ROLE) {
        depositCooldown = _cooldown;
        maxPendingTransactions = _maxPending;
    }

    /**
     * @dev Pause the contract
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @dev Unpause the contract
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    /**
     * @dev Emergency withdraw
     */
    function emergencyWithdraw(address _token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_token == address(0)) {
            payable(msg.sender).transfer(address(this).balance);
        } else {
            uint256 balance = IERC20(_token).balanceOf(address(this));
            IERC20(_token).safeTransfer(msg.sender, balance);
        }
    }

    // Receive function to accept native tokens
    receive() external payable {}
}

contracts/PolyOneChainFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title PolyOneChainFactory
 * @dev Enhanced smart contract for managing blockchain deployments on PolyOne
 * Features: Chain creation, pause/resume, upgrades, backups, scaling, deletion
 * Deployed on Polygon network
 */
contract PolyOneChainFactory is AccessControl, ReentrancyGuard, Pausable {
    using Counters for Counters.Counter;

    // Roles
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");

    // Chain status enum
    enum ChainStatus {
        Deploying,
        Active,
        Paused,
        Upgrading,
        Maintenance,
        Failed,
        Deleted
    }

    // Chain type enum
    enum ChainType {
        ZkRollup,
        OptimisticRollup,
        Validium
    }

    // Validator access enum
    enum ValidatorAccess {
        Public,
        Permissioned,
        Private
    }

    // Chain configuration struct
    struct ChainConfig {
        uint256 maxTps;
        uint256 blockGasLimit;
        uint256 blockTime; // in milliseconds
        uint256 maxValidators;
        bool bridgeEnabled;
        bool analyticsEnabled;
    }

    // Chain struct
    struct Chain {
        uint256 id;
        address owner;
        string name;
        string symbol;
        ChainType chainType;
        ValidatorAccess validatorAccess;
        string gasToken;
        uint256 validatorCount;
        ChainStatus status;
        uint256 createdAt;
        uint256 deployedAt;
        uint256 pausedAt;
        string rpcUrl;
        string explorerUrl;
        string bridgeUrl;
        ChainConfig config;
        uint256 currentVersion;
        bytes32 lastBackupHash;
    }

    // Upgrade struct
    struct ChainUpgrade {
        uint256 chainId;
        uint256 fromVersion;
        uint256 toVersion;
        address initiatedBy;
        uint256 scheduledAt;
        uint256 executedAt;
        bool executed;
        bool rolledBack;
        bytes upgradeData;
    }

    // Backup struct
    struct ChainBackup {
        uint256 chainId;
        bytes32 backupHash;
        uint256 blockHeight;
        uint256 createdAt;
        address createdBy;
        string storageLocation;
        bool isValid;
    }

    // State variables
    Counters.Counter private _chainIds;
    Counters.Counter private _upgradeIds;
    Counters.Counter private _backupIds;

    mapping(uint256 => Chain) public chains;
    mapping(address => uint256[]) public userChains;
    mapping(uint256 => ChainUpgrade) public upgrades;
    mapping(uint256 => ChainBackup) public backups;
    mapping(uint256 => uint256[]) public chainBackups;
    mapping(uint256 => uint256[]) public chainUpgrades;
    mapping(uint256 => mapping(address => bool)) public chainAdmins;

    // Fee configuration
    uint256 public deploymentFee;
    uint256 public upgradeMinDelay = 1 hours;
    address public feeCollector;

    // Events
    event ChainCreated(
        uint256 indexed chainId,
        address indexed owner,
        string name,
        ChainType chainType,
        uint256 timestamp
    );

    event ChainDeployed(
        uint256 indexed chainId,
        string rpcUrl,
        string explorerUrl,
        uint256 timestamp
    );

    event ChainPaused(
        uint256 indexed chainId,
        address indexed pausedBy,
        string reason,
        uint256 timestamp
    );

    event ChainResumed(
        uint256 indexed chainId,
        address indexed resumedBy,
        uint256 timestamp
    );

    event ChainUpgradeScheduled(
        uint256 indexed chainId,
        uint256 indexed upgradeId,
        uint256 fromVersion,
        uint256 toVersion,
        uint256 scheduledAt
    );

    event ChainUpgradeExecuted(
        uint256 indexed chainId,
        uint256 indexed upgradeId,
        uint256 toVersion,
        uint256 timestamp
    );

    event ChainUpgradeRolledBack(
        uint256 indexed chainId,
        uint256 indexed upgradeId,
        uint256 timestamp
    );

    event ChainBackupCreated(
        uint256 indexed chainId,
        uint256 indexed backupId,
        bytes32 backupHash,
        uint256 blockHeight,
        uint256 timestamp
    );

    event ChainBackupRestored(
        uint256 indexed chainId,
        uint256 indexed backupId,
        uint256 timestamp
    );

    event ChainScaled(
        uint256 indexed chainId,
        uint256 oldValidatorCount,
        uint256 newValidatorCount,
        uint256 timestamp
    );

    event ChainDeleted(
        uint256 indexed chainId,
        address indexed owner,
        uint256 timestamp
    );

    event ChainAdminAdded(
        uint256 indexed chainId,
        address indexed admin,
        address indexed addedBy
    );

    event ChainAdminRemoved(
        uint256 indexed chainId,
        address indexed admin,
        address indexed removedBy
    );

    event DeploymentFeeUpdated(uint256 oldFee, uint256 newFee);

    // Modifiers
    modifier onlyChainOwner(uint256 _chainId) {
        require(chains[_chainId].owner == msg.sender, "Not chain owner");
        _;
    }

    modifier onlyChainAdmin(uint256 _chainId) {
        require(
            chains[_chainId].owner == msg.sender || 
            chainAdmins[_chainId][msg.sender] ||
            hasRole(ADMIN_ROLE, msg.sender),
            "Not authorized"
        );
        _;
    }

    modifier chainExists(uint256 _chainId) {
        require(chains[_chainId].id != 0, "Chain does not exist");
        require(chains[_chainId].status != ChainStatus.Deleted, "Chain is deleted");
        _;
    }

    modifier chainActive(uint256 _chainId) {
        require(chains[_chainId].status == ChainStatus.Active, "Chain is not active");
        _;
    }

    constructor(address _feeCollector) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(OPERATOR_ROLE, msg.sender);
        
        feeCollector = _feeCollector;
        deploymentFee = 0.01 ether; // Default deployment fee
    }

    // ============================================================
    // CHAIN CREATION & DEPLOYMENT
    // ============================================================

    /**
     * @dev Create a new blockchain deployment
     */
    function createChain(
        string memory _name,
        string memory _symbol,
        ChainType _chainType,
        ValidatorAccess _validatorAccess,
        string memory _gasToken,
        uint256 _validatorCount,
        ChainConfig memory _config
    ) external payable whenNotPaused nonReentrant returns (uint256) {
        require(bytes(_name).length > 0, "Name required");
        require(bytes(_symbol).length > 0, "Symbol required");
        require(_validatorCount > 0 && _validatorCount <= 100, "Invalid validator count");
        require(msg.value >= deploymentFee, "Insufficient deployment fee");

        _chainIds.increment();
        uint256 newChainId = _chainIds.current();

        Chain storage newChain = chains[newChainId];
        newChain.id = newChainId;
        newChain.owner = msg.sender;
        newChain.name = _name;
        newChain.symbol = _symbol;
        newChain.chainType = _chainType;
        newChain.validatorAccess = _validatorAccess;
        newChain.gasToken = _gasToken;
        newChain.validatorCount = _validatorCount;
        newChain.status = ChainStatus.Deploying;
        newChain.createdAt = block.timestamp;
        newChain.config = _config;
        newChain.currentVersion = 1;

        userChains[msg.sender].push(newChainId);

        // Transfer deployment fee
        if (deploymentFee > 0) {
            payable(feeCollector).transfer(deploymentFee);
        }

        // Refund excess
        if (msg.value > deploymentFee) {
            payable(msg.sender).transfer(msg.value - deploymentFee);
        }

        emit ChainCreated(
            newChainId,
            msg.sender,
            _name,
            _chainType,
            block.timestamp
        );

        return newChainId;
    }

    /**
     * @dev Mark chain as deployed (called by operator after off-chain deployment)
     */
    function markChainDeployed(
        uint256 _chainId,
        string memory _rpcUrl,
        string memory _explorerUrl,
        string memory _bridgeUrl
    ) external onlyRole(OPERATOR_ROLE) chainExists(_chainId) {
        Chain storage chain = chains[_chainId];
        require(chain.status == ChainStatus.Deploying, "Chain not in deploying state");

        chain.rpcUrl = _rpcUrl;
        chain.explorerUrl = _explorerUrl;
        chain.bridgeUrl = _bridgeUrl;
        chain.status = ChainStatus.Active;
        chain.deployedAt = block.timestamp;

        emit ChainDeployed(_chainId, _rpcUrl, _explorerUrl, block.timestamp);
    }

    // ============================================================
    // PAUSE & RESUME
    // ============================================================

    /**
     * @dev Pause a chain
     */
    function pauseChain(uint256 _chainId, string memory _reason) 
        external 
        onlyChainAdmin(_chainId) 
        chainExists(_chainId)
        chainActive(_chainId) 
    {
        Chain storage chain = chains[_chainId];
        chain.status = ChainStatus.Paused;
        chain.pausedAt = block.timestamp;

        emit ChainPaused(_chainId, msg.sender, _reason, block.timestamp);
    }

    /**
     * @dev Resume a paused chain
     */
    function resumeChain(uint256 _chainId) 
        external 
        onlyChainAdmin(_chainId) 
        chainExists(_chainId) 
    {
        Chain storage chain = chains[_chainId];
        require(chain.status == ChainStatus.Paused, "Chain is not paused");

        chain.status = ChainStatus.Active;
        chain.pausedAt = 0;

        emit ChainResumed(_chainId, msg.sender, block.timestamp);
    }

    // ============================================================
    // UPGRADES
    // ============================================================

    /**
     * @dev Schedule a chain upgrade
     */
    function scheduleUpgrade(
        uint256 _chainId,
        uint256 _toVersion,
        uint256 _scheduledAt,
        bytes memory _upgradeData
    ) external onlyChainAdmin(_chainId) chainExists(_chainId) returns (uint256) {
        require(_scheduledAt >= block.timestamp + upgradeMinDelay, "Scheduled time too soon");
        
        Chain storage chain = chains[_chainId];
        require(_toVersion > chain.currentVersion, "New version must be higher");

        _upgradeIds.increment();
        uint256 upgradeId = _upgradeIds.current();

        ChainUpgrade storage upgrade = upgrades[upgradeId];
        upgrade.chainId = _chainId;
        upgrade.fromVersion = chain.currentVersion;
        upgrade.toVersion = _toVersion;
        upgrade.initiatedBy = msg.sender;
        upgrade.scheduledAt = _scheduledAt;
        upgrade.upgradeData = _upgradeData;

        chainUpgrades[_chainId].push(upgradeId);

        emit ChainUpgradeScheduled(
            _chainId,
            upgradeId,
            chain.currentVersion,
            _toVersion,
            _scheduledAt
        );

        return upgradeId;
    }

    /**
     * @dev Execute a scheduled upgrade
     */
    function executeUpgrade(uint256 _upgradeId) 
        external 
        onlyRole(OPERATOR_ROLE) 
        nonReentrant 
    {
        ChainUpgrade storage upgrade = upgrades[_upgradeId];
        require(!upgrade.executed, "Upgrade already executed");
        require(!upgrade.rolledBack, "Upgrade was rolled back");
        require(block.timestamp >= upgrade.scheduledAt, "Upgrade not yet scheduled");

        Chain storage chain = chains[upgrade.chainId];
        require(chain.status != ChainStatus.Deleted, "Chain is deleted");

        chain.status = ChainStatus.Upgrading;
        
        // Execute upgrade logic (in production, this would trigger off-chain processes)
        chain.currentVersion = upgrade.toVersion;
        upgrade.executed = true;
        upgrade.executedAt = block.timestamp;
        
        chain.status = ChainStatus.Active;

        emit ChainUpgradeExecuted(
            upgrade.chainId,
            _upgradeId,
            upgrade.toVersion,
            block.timestamp
        );
    }

    /**
     * @dev Rollback an upgrade
     */
    function rollbackUpgrade(uint256 _upgradeId) 
        external 
        onlyRole(OPERATOR_ROLE) 
        nonReentrant 
    {
        ChainUpgrade storage upgrade = upgrades[_upgradeId];
        require(upgrade.executed, "Upgrade not executed");
        require(!upgrade.rolledBack, "Already rolled back");

        Chain storage chain = chains[upgrade.chainId];
        chain.currentVersion = upgrade.fromVersion;
        upgrade.rolledBack = true;

        emit ChainUpgradeRolledBack(upgrade.chainId, _upgradeId, block.timestamp);
    }

    // ============================================================
    // BACKUPS
    // ============================================================

    /**
     * @dev Create a chain backup
     */
    function createBackup(
        uint256 _chainId,
        bytes32 _backupHash,
        uint256 _blockHeight,
        string memory _storageLocation
    ) external onlyRole(OPERATOR_ROLE) chainExists(_chainId) returns (uint256) {
        _backupIds.increment();
        uint256 backupId = _backupIds.current();

        ChainBackup storage backup = backups[backupId];
        backup.chainId = _chainId;
        backup.backupHash = _backupHash;
        backup.blockHeight = _blockHeight;
        backup.createdAt = block.timestamp;
        backup.createdBy = msg.sender;
        backup.storageLocation = _storageLocation;
        backup.isValid = true;

        chainBackups[_chainId].push(backupId);
        chains[_chainId].lastBackupHash = _backupHash;

        emit ChainBackupCreated(
            _chainId,
            backupId,
            _backupHash,
            _blockHeight,
            block.timestamp
        );

        return backupId;
    }

    /**
     * @dev Mark backup as restored
     */
    function markBackupRestored(uint256 _backupId) 
        external 
        onlyRole(OPERATOR_ROLE) 
    {
        ChainBackup storage backup = backups[_backupId];
        require(backup.isValid, "Invalid backup");

        emit ChainBackupRestored(backup.chainId, _backupId, block.timestamp);
    }

    /**
     * @dev Invalidate a backup
     */
    function invalidateBackup(uint256 _backupId) 
        external 
        onlyRole(OPERATOR_ROLE) 
    {
        backups[_backupId].isValid = false;
    }

    // ============================================================
    // SCALING
    // ============================================================

    /**
     * @dev Scale chain validators
     */
    function scaleChain(uint256 _chainId, uint256 _newValidatorCount) 
        external 
        onlyChainAdmin(_chainId) 
        chainExists(_chainId) 
    {
        require(_newValidatorCount > 0 && _newValidatorCount <= 100, "Invalid validator count");
        
        Chain storage chain = chains[_chainId];
        uint256 oldCount = chain.validatorCount;
        require(_newValidatorCount != oldCount, "Same validator count");

        chain.validatorCount = _newValidatorCount;

        emit ChainScaled(_chainId, oldCount, _newValidatorCount, block.timestamp);
    }

    // ============================================================
    // DELETION
    // ============================================================

    /**
     * @dev Delete a chain (soft delete)
     */
    function deleteChain(uint256 _chainId) 
        external 
        onlyChainOwner(_chainId) 
        chainExists(_chainId) 
    {
        Chain storage chain = chains[_chainId];
        require(
            chain.status == ChainStatus.Paused || 
            chain.status == ChainStatus.Failed,
            "Chain must be paused or failed to delete"
        );

        chain.status = ChainStatus.Deleted;

        emit ChainDeleted(_chainId, msg.sender, block.timestamp);
    }

    // ============================================================
    // CHAIN ADMIN MANAGEMENT
    // ============================================================

    /**
     * @dev Add a chain admin
     */
    function addChainAdmin(uint256 _chainId, address _admin) 
        external 
        onlyChainOwner(_chainId) 
        chainExists(_chainId) 
    {
        require(_admin != address(0), "Invalid address");
        require(!chainAdmins[_chainId][_admin], "Already admin");

        chainAdmins[_chainId][_admin] = true;

        emit ChainAdminAdded(_chainId, _admin, msg.sender);
    }

    /**
     * @dev Remove a chain admin
     */
    function removeChainAdmin(uint256 _chainId, address _admin) 
        external 
        onlyChainOwner(_chainId) 
        chainExists(_chainId) 
    {
        require(chainAdmins[_chainId][_admin], "Not an admin");

        chainAdmins[_chainId][_admin] = false;

        emit ChainAdminRemoved(_chainId, _admin, msg.sender);
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    /**
     * @dev Get all chains for a user
     */
    function getUserChains(address _user) external view returns (uint256[] memory) {
        return userChains[_user];
    }

    /**
     * @dev Get chain details
     */
    function getChain(uint256 _chainId) external view returns (Chain memory) {
        return chains[_chainId];
    }

    /**
     * @dev Get all backups for a chain
     */
    function getChainBackups(uint256 _chainId) external view returns (uint256[] memory) {
        return chainBackups[_chainId];
    }

    /**
     * @dev Get all upgrades for a chain
     */
    function getChainUpgrades(uint256 _chainId) external view returns (uint256[] memory) {
        return chainUpgrades[_chainId];
    }

    /**
     * @dev Get backup details
     */
    function getBackup(uint256 _backupId) external view returns (ChainBackup memory) {
        return backups[_backupId];
    }

    /**
     * @dev Get upgrade details
     */
    function getUpgrade(uint256 _upgradeId) external view returns (ChainUpgrade memory) {
        return upgrades[_upgradeId];
    }

    /**
     * @dev Get total number of chains
     */
    function getTotalChains() external view returns (uint256) {
        return _chainIds.current();
    }

    /**
     * @dev Check if address is chain admin
     */
    function isChainAdmin(uint256 _chainId, address _addr) external view returns (bool) {
        return chainAdmins[_chainId][_addr] || 
               chains[_chainId].owner == _addr ||
               hasRole(ADMIN_ROLE, _addr);
    }

    // ============================================================
    // ADMIN FUNCTIONS
    // ============================================================

    /**
     * @dev Update deployment fee
     */
    function setDeploymentFee(uint256 _newFee) external onlyRole(ADMIN_ROLE) {
        uint256 oldFee = deploymentFee;
        deploymentFee = _newFee;
        emit DeploymentFeeUpdated(oldFee, _newFee);
    }

    /**
     * @dev Update fee collector address
     */
    function setFeeCollector(address _newCollector) external onlyRole(ADMIN_ROLE) {
        require(_newCollector != address(0), "Invalid address");
        feeCollector = _newCollector;
    }

    /**
     * @dev Update minimum upgrade delay
     */
    function setUpgradeMinDelay(uint256 _delay) external onlyRole(ADMIN_ROLE) {
        upgradeMinDelay = _delay;
    }

    /**
     * @dev Pause the contract
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @dev Unpause the contract
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    /**
     * @dev Emergency withdraw
     */
    function emergencyWithdraw() external onlyRole(DEFAULT_ADMIN_ROLE) {
        payable(msg.sender).transfer(address(this).balance);
    }
}

contracts/ValidatorRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title ValidatorRegistry
 * @dev Smart contract for managing validators with staking, rewards, and slashing
 * Features: Add/remove validators, staking, rewards distribution, slashing, performance monitoring
 */
contract ValidatorRegistry is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;
    using Counters for Counters.Counter;

    // Roles
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant SLASHER_ROLE = keccak256("SLASHER_ROLE");

    // Validator status enum
    enum ValidatorStatus {
        Pending,
        Active,
        Inactive,
        Jailed,
        Unbonding,
        Slashed,
        Removed
    }

    // Validator struct
    struct Validator {
        uint256 id;
        uint256 chainId;
        address owner;
        address validatorAddress;
        bytes publicKey;
        string name;
        ValidatorStatus status;
        uint256 stakeAmount;
        uint256 minStakeRequired;
        uint256 commissionRate; // basis points (e.g., 500 = 5%)
        uint256 rewardsEarned;
        uint256 rewardsClaimed;
        uint256 delegationsReceived;
        uint256 delegatorsCount;
        uint256 blocksProduced;
        uint256 blocksMissed;
        uint256 slashCount;
        uint256 totalSlashed;
        uint256 jailUntil;
        uint256 createdAt;
        uint256 activatedAt;
        uint256 lastActiveAt;
        bool isGenesis;
    }

    // Delegation struct
    struct Delegation {
        uint256 validatorId;
        address delegator;
        uint256 amount;
        uint256 rewardsEarned;
        uint256 rewardsClaimed;
        uint256 delegatedAt;
        uint256 undelegateRequestedAt;
        bool isActive;
    }

    // Performance record struct
    struct PerformanceRecord {
        uint256 validatorId;
        uint256 blocksProduced;
        uint256 blocksMissed;
        uint256 transactionsProcessed;
        uint256 uptimeSeconds;
        uint256 avgResponseTimeMs;
        uint256 rewardsEarned;
        uint256 periodStart;
        uint256 periodEnd;
    }

    // Slash event struct
    struct SlashEvent {
        uint256 validatorId;
        uint256 amount;
        string reason;
        uint256 slashedAt;
        address slashedBy;
        bool jailed;
        uint256 jailDuration;
    }

    // State variables
    Counters.Counter private _validatorIds;
    Counters.Counter private _delegationIds;
    Counters.Counter private _performanceIds;
    Counters.Counter private _slashIds;

    IERC20 public stakingToken;
    
    mapping(uint256 => Validator) public validators;
    mapping(uint256 => mapping(address => bool)) public chainValidators; // chainId => validatorAddr => exists
    mapping(address => uint256[]) public validatorsByOwner;
    mapping(uint256 => uint256[]) public validatorsByChain;
    
    mapping(uint256 => Delegation) public delegations;
    mapping(address => uint256[]) public delegationsByDelegator;
    mapping(uint256 => uint256[]) public delegationsByValidator;
    
    mapping(uint256 => PerformanceRecord[]) public performanceHistory;
    mapping(uint256 => SlashEvent[]) public slashHistory;

    // Configuration
    uint256 public minStake = 1000 ether;
    uint256 public maxCommissionRate = 2000; // 20%
    uint256 public unbondingPeriod = 14 days;
    uint256 public slashJailDuration = 7 days;
    uint256 public minSlashAmount = 100 ether;
    uint256 public maxSlashPercentage = 5000; // 50%

    // Events
    event ValidatorRegistered(
        uint256 indexed validatorId,
        uint256 indexed chainId,
        address indexed owner,
        address validatorAddress,
        string name,
        uint256 timestamp
    );

    event ValidatorActivated(
        uint256 indexed validatorId,
        uint256 indexed chainId,
        uint256 timestamp
    );

    event ValidatorDeactivated(
        uint256 indexed validatorId,
        uint256 indexed chainId,
        string reason,
        uint256 timestamp
    );

    event ValidatorRemoved(
        uint256 indexed validatorId,
        uint256 indexed chainId,
        uint256 timestamp
    );

    event StakeAdded(
        uint256 indexed validatorId,
        address indexed staker,
        uint256 amount,
        uint256 newTotal,
        uint256 timestamp
    );

    event StakeWithdrawn(
        uint256 indexed validatorId,
        address indexed staker,
        uint256 amount,
        uint256 remaining,
        uint256 timestamp
    );

    event DelegationAdded(
        uint256 indexed delegationId,
        uint256 indexed validatorId,
        address indexed delegator,
        uint256 amount,
        uint256 timestamp
    );

    event DelegationRemoved(
        uint256 indexed delegationId,
        uint256 indexed validatorId,
        address indexed delegator,
        uint256 amount,
        uint256 timestamp
    );

    event RewardsDistributed(
        uint256 indexed validatorId,
        uint256 validatorReward,
        uint256 delegatorsReward,
        uint256 timestamp
    );

    event RewardsClaimed(
        uint256 indexed validatorId,
        address indexed claimant,
        uint256 amount,
        uint256 timestamp
    );

    event ValidatorSlashed(
        uint256 indexed validatorId,
        uint256 indexed slashId,
        uint256 amount,
        string reason,
        bool jailed,
        uint256 timestamp
    );

    event ValidatorUnjailed(
        uint256 indexed validatorId,
        uint256 timestamp
    );

    event PerformanceRecorded(
        uint256 indexed validatorId,
        uint256 blocksProduced,
        uint256 blocksMissed,
        uint256 periodStart,
        uint256 periodEnd
    );

    event CommissionRateUpdated(
        uint256 indexed validatorId,
        uint256 oldRate,
        uint256 newRate
    );

    // Modifiers
    modifier onlyValidatorOwner(uint256 _validatorId) {
        require(validators[_validatorId].owner == msg.sender, "Not validator owner");
        _;
    }

    modifier validatorExists(uint256 _validatorId) {
        require(validators[_validatorId].id != 0, "Validator does not exist");
        _;
    }

    modifier validatorActive(uint256 _validatorId) {
        require(validators[_validatorId].status == ValidatorStatus.Active, "Validator not active");
        _;
    }

    constructor(address _stakingToken) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(OPERATOR_ROLE, msg.sender);
        _grantRole(SLASHER_ROLE, msg.sender);
        
        stakingToken = IERC20(_stakingToken);
    }

    // ============================================================
    // VALIDATOR REGISTRATION
    // ============================================================

    /**
     * @dev Register a new validator
     */
    function registerValidator(
        uint256 _chainId,
        address _validatorAddress,
        bytes memory _publicKey,
        string memory _name,
        uint256 _commissionRate,
        bool _isGenesis
    ) external whenNotPaused nonReentrant returns (uint256) {
        require(_validatorAddress != address(0), "Invalid validator address");
        require(!chainValidators[_chainId][_validatorAddress], "Validator already exists for chain");
        require(_commissionRate <= maxCommissionRate, "Commission too high");
        require(bytes(_publicKey).length > 0, "Public key required");

        _validatorIds.increment();
        uint256 validatorId = _validatorIds.current();

        Validator storage validator = validators[validatorId];
        validator.id = validatorId;
        validator.chainId = _chainId;
        validator.owner = msg.sender;
        validator.validatorAddress = _validatorAddress;
        validator.publicKey = _publicKey;
        validator.name = _name;
        validator.status = ValidatorStatus.Pending;
        validator.commissionRate = _commissionRate;
        validator.minStakeRequired = minStake;
        validator.createdAt = block.timestamp;
        validator.isGenesis = _isGenesis;

        chainValidators[_chainId][_validatorAddress] = true;
        validatorsByOwner[msg.sender].push(validatorId);
        validatorsByChain[_chainId].push(validatorId);

        emit ValidatorRegistered(
            validatorId,
            _chainId,
            msg.sender,
            _validatorAddress,
            _name,
            block.timestamp
        );

        return validatorId;
    }

    /**
     * @dev Activate a validator (requires minimum stake)
     */
    function activateValidator(uint256 _validatorId) 
        external 
        onlyRole(OPERATOR_ROLE) 
        validatorExists(_validatorId) 
    {
        Validator storage validator = validators[_validatorId];
        require(validator.status == ValidatorStatus.Pending || validator.status == ValidatorStatus.Inactive, 
                "Invalid status");
        require(validator.stakeAmount >= validator.minStakeRequired, "Insufficient stake");

        validator.status = ValidatorStatus.Active;
        validator.activatedAt = block.timestamp;
        validator.lastActiveAt = block.timestamp;

        emit ValidatorActivated(_validatorId, validator.chainId, block.timestamp);
    }

    /**
     * @dev Deactivate a validator
     */
    function deactivateValidator(uint256 _validatorId, string memory _reason) 
        external 
        onlyValidatorOwner(_validatorId) 
        validatorExists(_validatorId) 
    {
        Validator storage validator = validators[_validatorId];
        require(validator.status == ValidatorStatus.Active, "Not active");

        validator.status = ValidatorStatus.Inactive;

        emit ValidatorDeactivated(_validatorId, validator.chainId, _reason, block.timestamp);
    }

    /**
     * @dev Remove a validator completely
     */
    function removeValidator(uint256 _validatorId) 
        external 
        onlyValidatorOwner(_validatorId) 
        validatorExists(_validatorId) 
    {
        Validator storage validator = validators[_validatorId];
        require(
            validator.status == ValidatorStatus.Inactive || 
            validator.status == ValidatorStatus.Slashed,
            "Must be inactive or slashed"
        );
        require(validator.delegationsReceived == 0, "Has active delegations");
        require(block.timestamp >= validator.jailUntil, "Still jailed");

        // Return remaining stake
        if (validator.stakeAmount > 0) {
            uint256 returnAmount = validator.stakeAmount;
            validator.stakeAmount = 0;
            stakingToken.safeTransfer(validator.owner, returnAmount);
        }

        validator.status = ValidatorStatus.Removed;
        chainValidators[validator.chainId][validator.validatorAddress] = false;

        emit ValidatorRemoved(_validatorId, validator.chainId, block.timestamp);
    }

    // ============================================================
    // STAKING
    // ============================================================

    /**
     * @dev Add stake to a validator
     */
    function addStake(uint256 _validatorId, uint256 _amount) 
        external 
        onlyValidatorOwner(_validatorId) 
        validatorExists(_validatorId) 
        nonReentrant 
    {
        require(_amount > 0, "Amount must be positive");
        
        Validator storage validator = validators[_validatorId];
        require(
            validator.status != ValidatorStatus.Removed && 
            validator.status != ValidatorStatus.Slashed,
            "Cannot stake"
        );

        stakingToken.safeTransferFrom(msg.sender, address(this), _amount);
        validator.stakeAmount += _amount;

        emit StakeAdded(_validatorId, msg.sender, _amount, validator.stakeAmount, block.timestamp);
    }

    /**
     * @dev Withdraw stake from a validator
     */
    function withdrawStake(uint256 _validatorId, uint256 _amount) 
        external 
        onlyValidatorOwner(_validatorId) 
        validatorExists(_validatorId) 
        nonReentrant 
    {
        Validator storage validator = validators[_validatorId];
        require(_amount > 0 && _amount <= validator.stakeAmount, "Invalid amount");
        
        // Check if validator will still meet minimum stake if active
        if (validator.status == ValidatorStatus.Active) {
            require(
                validator.stakeAmount - _amount >= validator.minStakeRequired,
                "Would go below min stake"
            );
        }

        validator.stakeAmount -= _amount;
        stakingToken.safeTransfer(msg.sender, _amount);

        emit StakeWithdrawn(_validatorId, msg.sender, _amount, validator.stakeAmount, block.timestamp);
    }

    // ============================================================
    // DELEGATION
    // ============================================================

    /**
     * @dev Delegate tokens to a validator
     */
    function delegate(uint256 _validatorId, uint256 _amount) 
        external 
        validatorExists(_validatorId) 
        validatorActive(_validatorId) 
        nonReentrant 
        returns (uint256) 
    {
        require(_amount > 0, "Amount must be positive");

        stakingToken.safeTransferFrom(msg.sender, address(this), _amount);

        _delegationIds.increment();
        uint256 delegationId = _delegationIds.current();

        Delegation storage delegation = delegations[delegationId];
        delegation.validatorId = _validatorId;
        delegation.delegator = msg.sender;
        delegation.amount = _amount;
        delegation.delegatedAt = block.timestamp;
        delegation.isActive = true;

        delegationsByDelegator[msg.sender].push(delegationId);
        delegationsByValidator[_validatorId].push(delegationId);

        Validator storage validator = validators[_validatorId];
        validator.delegationsReceived += _amount;
        validator.delegatorsCount++;

        emit DelegationAdded(delegationId, _validatorId, msg.sender, _amount, block.timestamp);

        return delegationId;
    }

    /**
     * @dev Request to undelegate (starts unbonding period)
     */
    function requestUndelegate(uint256 _delegationId) 
        external 
        nonReentrant 
    {
        Delegation storage delegation = delegations[_delegationId];
        require(delegation.delegator == msg.sender, "Not delegator");
        require(delegation.isActive, "Not active");
        require(delegation.undelegateRequestedAt == 0, "Already requested");

        delegation.undelegateRequestedAt = block.timestamp;
    }

    /**
     * @dev Complete undelegation after unbonding period
     */
    function completeUndelegate(uint256 _delegationId) 
        external 
        nonReentrant 
    {
        Delegation storage delegation = delegations[_delegationId];
        require(delegation.delegator == msg.sender, "Not delegator");
        require(delegation.isActive, "Not active");
        require(delegation.undelegateRequestedAt > 0, "Not requested");
        require(
            block.timestamp >= delegation.undelegateRequestedAt + unbondingPeriod,
            "Unbonding period not over"
        );

        uint256 amount = delegation.amount;
        uint256 rewards = delegation.rewardsEarned - delegation.rewardsClaimed;

        Validator storage validator = validators[delegation.validatorId];
        validator.delegationsReceived -= amount;
        validator.delegatorsCount--;

        delegation.isActive = false;
        delegation.amount = 0;

        // Transfer principal + unclaimed rewards
        stakingToken.safeTransfer(msg.sender, amount + rewards);

        emit DelegationRemoved(
            _delegationId, 
            delegation.validatorId, 
            msg.sender, 
            amount, 
            block.timestamp
        );
    }

    // ============================================================
    // REWARDS
    // ============================================================

    /**
     * @dev Distribute rewards to a validator and their delegators
     */
    function distributeRewards(uint256 _validatorId, uint256 _totalReward) 
        external 
        onlyRole(OPERATOR_ROLE) 
        validatorExists(_validatorId) 
        nonReentrant 
    {
        require(_totalReward > 0, "No rewards to distribute");

        Validator storage validator = validators[_validatorId];
        
        // Calculate commission for validator
        uint256 validatorCommission = (_totalReward * validator.commissionRate) / 10000;
        uint256 delegatorsReward = _totalReward - validatorCommission;

        // Add commission to validator rewards
        validator.rewardsEarned += validatorCommission;

        // Distribute to delegators proportionally
        if (validator.delegationsReceived > 0) {
            uint256[] memory validatorDelegations = delegationsByValidator[_validatorId];
            for (uint256 i = 0; i < validatorDelegations.length; i++) {
                Delegation storage delegation = delegations[validatorDelegations[i]];
                if (delegation.isActive) {
                    uint256 delegatorShare = (delegatorsReward * delegation.amount) / validator.delegationsReceived;
                    delegation.rewardsEarned += delegatorShare;
                }
            }
        } else {
            // If no delegators, all rewards go to validator
            validator.rewardsEarned += delegatorsReward;
        }

        // Transfer rewards to contract
        stakingToken.safeTransferFrom(msg.sender, address(this), _totalReward);

        emit RewardsDistributed(_validatorId, validatorCommission, delegatorsReward, block.timestamp);
    }

    /**
     * @dev Claim validator rewards
     */
    function claimValidatorRewards(uint256 _validatorId) 
        external 
        onlyValidatorOwner(_validatorId) 
        validatorExists(_validatorId) 
        nonReentrant 
    {
        Validator storage validator = validators[_validatorId];
        uint256 claimable = validator.rewardsEarned - validator.rewardsClaimed;
        require(claimable > 0, "No rewards to claim");

        validator.rewardsClaimed += claimable;
        stakingToken.safeTransfer(msg.sender, claimable);

        emit RewardsClaimed(_validatorId, msg.sender, claimable, block.timestamp);
    }

    /**
     * @dev Claim delegator rewards
     */
    function claimDelegatorRewards(uint256 _delegationId) 
        external 
        nonReentrant 
    {
        Delegation storage delegation = delegations[_delegationId];
        require(delegation.delegator == msg.sender, "Not delegator");
        
        uint256 claimable = delegation.rewardsEarned - delegation.rewardsClaimed;
        require(claimable > 0, "No rewards to claim");

        delegation.rewardsClaimed += claimable;
        stakingToken.safeTransfer(msg.sender, claimable);

        emit RewardsClaimed(delegation.validatorId, msg.sender, claimable, block.timestamp);
    }

    // ============================================================
    // SLASHING
    // ============================================================

    /**
     * @dev Slash a validator for misbehavior
     */
    function slashValidator(
        uint256 _validatorId,
        uint256 _percentage, // basis points
        string memory _reason,
        bool _jail
    ) external onlyRole(SLASHER_ROLE) validatorExists(_validatorId) nonReentrant {
        require(_percentage > 0 && _percentage <= maxSlashPercentage, "Invalid slash percentage");

        Validator storage validator = validators[_validatorId];
        
        uint256 totalStake = validator.stakeAmount + validator.delegationsReceived;
        uint256 slashAmount = (totalStake * _percentage) / 10000;
        
        if (slashAmount < minSlashAmount) {
            slashAmount = minSlashAmount > totalStake ? totalStake : minSlashAmount;
        }

        // Slash from validator stake first
        uint256 fromValidator = slashAmount > validator.stakeAmount ? validator.stakeAmount : slashAmount;
        validator.stakeAmount -= fromValidator;
        
        // If more to slash, take from delegations proportionally
        if (slashAmount > fromValidator && validator.delegationsReceived > 0) {
            uint256 remainingSlash = slashAmount - fromValidator;
            uint256[] memory validatorDelegations = delegationsByValidator[_validatorId];
            
            for (uint256 i = 0; i < validatorDelegations.length; i++) {
                Delegation storage delegation = delegations[validatorDelegations[i]];
                if (delegation.isActive) {
                    uint256 delegatorSlash = (remainingSlash * delegation.amount) / validator.delegationsReceived;
                    delegation.amount -= delegatorSlash;
                }
            }
            validator.delegationsReceived -= remainingSlash;
        }

        validator.slashCount++;
        validator.totalSlashed += slashAmount;

        if (_jail) {
            validator.status = ValidatorStatus.Jailed;
            validator.jailUntil = block.timestamp + slashJailDuration;
        }

        _slashIds.increment();
        uint256 slashId = _slashIds.current();

        SlashEvent memory slashEvent = SlashEvent({
            validatorId: _validatorId,
            amount: slashAmount,
            reason: _reason,
            slashedAt: block.timestamp,
            slashedBy: msg.sender,
            jailed: _jail,
            jailDuration: _jail ? slashJailDuration : 0
        });
        slashHistory[_validatorId].push(slashEvent);

        emit ValidatorSlashed(_validatorId, slashId, slashAmount, _reason, _jail, block.timestamp);
    }

    /**
     * @dev Unjail a validator after jail period
     */
    function unjailValidator(uint256 _validatorId) 
        external 
        onlyValidatorOwner(_validatorId) 
        validatorExists(_validatorId) 
    {
        Validator storage validator = validators[_validatorId];
        require(validator.status == ValidatorStatus.Jailed, "Not jailed");
        require(block.timestamp >= validator.jailUntil, "Still in jail");
        require(validator.stakeAmount >= validator.minStakeRequired, "Insufficient stake");

        validator.status = ValidatorStatus.Active;
        validator.jailUntil = 0;

        emit ValidatorUnjailed(_validatorId, block.timestamp);
    }

    // ============================================================
    // PERFORMANCE MONITORING
    // ============================================================

    /**
     * @dev Record validator performance
     */
    function recordPerformance(
        uint256 _validatorId,
        uint256 _blocksProduced,
        uint256 _blocksMissed,
        uint256 _transactionsProcessed,
        uint256 _uptimeSeconds,
        uint256 _avgResponseTimeMs,
        uint256 _rewardsEarned,
        uint256 _periodStart,
        uint256 _periodEnd
    ) external onlyRole(OPERATOR_ROLE) validatorExists(_validatorId) {
        Validator storage validator = validators[_validatorId];
        validator.blocksProduced += _blocksProduced;
        validator.blocksMissed += _blocksMissed;
        validator.lastActiveAt = block.timestamp;

        PerformanceRecord memory record = PerformanceRecord({
            validatorId: _validatorId,
            blocksProduced: _blocksProduced,
            blocksMissed: _blocksMissed,
            transactionsProcessed: _transactionsProcessed,
            uptimeSeconds: _uptimeSeconds,
            avgResponseTimeMs: _avgResponseTimeMs,
            rewardsEarned: _rewardsEarned,
            periodStart: _periodStart,
            periodEnd: _periodEnd
        });
        performanceHistory[_validatorId].push(record);

        emit PerformanceRecorded(_validatorId, _blocksProduced, _blocksMissed, _periodStart, _periodEnd);
    }

    // ============================================================
    // CONFIGURATION
    // ============================================================

    /**
     * @dev Update validator commission rate
     */
    function updateCommissionRate(uint256 _validatorId, uint256 _newRate) 
        external 
        onlyValidatorOwner(_validatorId) 
        validatorExists(_validatorId) 
    {
        require(_newRate <= maxCommissionRate, "Rate too high");
        
        Validator storage validator = validators[_validatorId];
        uint256 oldRate = validator.commissionRate;
        validator.commissionRate = _newRate;

        emit CommissionRateUpdated(_validatorId, oldRate, _newRate);
    }

    // ============================================================
    // VIEW FUNCTIONS
    // ============================================================

    /**
     * @dev Get validator details
     */
    function getValidator(uint256 _validatorId) external view returns (Validator memory) {
        return validators[_validatorId];
    }

    /**
     * @dev Get validators by chain
     */
    function getValidatorsByChain(uint256 _chainId) external view returns (uint256[] memory) {
        return validatorsByChain[_chainId];
    }

    /**
     * @dev Get validators by owner
     */
    function getValidatorsByOwner(address _owner) external view returns (uint256[] memory) {
        return validatorsByOwner[_owner];
    }

    /**
     * @dev Get delegation details
     */
    function getDelegation(uint256 _delegationId) external view returns (Delegation memory) {
        return delegations[_delegationId];
    }

    /**
     * @dev Get delegations by delegator
     */
    function getDelegationsByDelegator(address _delegator) external view returns (uint256[] memory) {
        return delegationsByDelegator[_delegator];
    }

    /**
     * @dev Get delegations by validator
     */
    function getDelegationsByValidator(uint256 _validatorId) external view returns (uint256[] memory) {
        return delegationsByValidator[_validatorId];
    }

    /**
     * @dev Get performance history
     */
    function getPerformanceHistory(uint256 _validatorId) external view returns (PerformanceRecord[] memory) {
        return performanceHistory[_validatorId];
    }

    /**
     * @dev Get slash history
     */
    function getSlashHistory(uint256 _validatorId) external view returns (SlashEvent[] memory) {
        return slashHistory[_validatorId];
    }

    /**
     * @dev Get total validators count
     */
    function getTotalValidators() external view returns (uint256) {
        return _validatorIds.current();
    }

    /**
     * @dev Calculate effective stake (own stake + delegations)
     */
    function getEffectiveStake(uint256 _validatorId) external view returns (uint256) {
        Validator storage validator = validators[_validatorId];
        return validator.stakeAmount + validator.delegationsReceived;
    }

    // ============================================================
    // ADMIN FUNCTIONS
    // ============================================================

    /**
     * @dev Update minimum stake requirement
     */
    function setMinStake(uint256 _minStake) external onlyRole(ADMIN_ROLE) {
        minStake = _minStake;
    }

    /**
     * @dev Update maximum commission rate
     */
    function setMaxCommissionRate(uint256 _maxRate) external onlyRole(ADMIN_ROLE) {
        require(_maxRate <= 10000, "Cannot exceed 100%");
        maxCommissionRate = _maxRate;
    }

    /**
     * @dev Update unbonding period
     */
    function setUnbondingPeriod(uint256 _period) external onlyRole(ADMIN_ROLE) {
        unbondingPeriod = _period;
    }

    /**
     * @dev Update slash parameters
     */
    function setSlashParams(
        uint256 _jailDuration,
        uint256 _minSlashAmount,
        uint256 _maxSlashPercentage
    ) external onlyRole(ADMIN_ROLE) {
        require(_maxSlashPercentage <= 10000, "Cannot exceed 100%");
        slashJailDuration = _jailDuration;
        minSlashAmount = _minSlashAmount;
        maxSlashPercentage = _maxSlashPercentage;
    }

    /**
     * @dev Pause the contract
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /**
     * @dev Unpause the contract
     */
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
}

